const input=$json.body??$json;
const s=v=>String(v??'').trim();
const strategy=input.offer_strategy??input.strategy??{};
const identity=input.identity??{};
const leadId=s(identity.lead_id);
const propertyId=s(identity.property_id);
const dealId=s(identity.deal_id);
const requestId=s(input.request_id??strategy.request_id);
const offer=Number(strategy.target_offer??strategy.recommended_offer??input.target_offer??input.recommended_offer);
const mao=Number(strategy.mao_ceiling??input.mao_ceiling??input.mao);
const underwritingStatus=s(input.underwriting_status??input.underwriting?.status??strategy.underwriting_status).toLowerCase();
const strategyStatus=s(strategy.status??input.strategy_status).toLowerCase();
const autonomous=input.autonomous_opt_in===true;
const humanApproval=input.human_approval===true||input.approval_granted===true;
const deliveryMode=s(input.delivery_mode??'review_then_send').toLowerCase();
const missing=[];
if(!leadId)missing.push('lead_id');
if(!propertyId&&!dealId)missing.push('property_or_deal_id');
if(!Number.isFinite(offer)||offer<=0)missing.push('offer_amount');
if(!Number.isFinite(mao)||mao<=0)missing.push('mao_ceiling');
if(Number.isFinite(offer)&&Number.isFinite(mao)&&offer>mao)missing.push('offer_exceeds_mao');
if(!['approved','ready','proceed','approved_with_conditions'].includes(underwritingStatus))missing.push('approved_underwriting');
if(strategyStatus!=='ready')missing.push('offer_strategy_ready');
const approvalRequired=deliveryMode!=='draft_only';
const dispatchAllowed=missing.length===0&&(!approvalRequired||humanApproval)&&autonomous;
const status=missing.length?'blocked':dispatchAllowed?'dispatch_ready':approvalRequired&&!humanApproval?'approval_required':'ready_for_review';
const guardrails={never_exceed_mao:true,approved_underwriting_required:true,human_approval_required_for_delivery:approvalRequired,autonomous_opt_in_required:true};
const approvalId='offer-approval:'+s(dealId||propertyId||leadId||'unknown')+':'+s(requestId||'unknown')+':v1';
const activity={activity_type:'offer_approval_gate',subject:'AI offer approval gate '+status,body:[
'Offer approval gate evaluated by Wholesaling OS.',
'Offer amount: '+String(offer),
'MAO ceiling: '+String(mao),
'Underwriting status: '+underwritingStatus,
'Strategy status: '+strategyStatus,
'Delivery mode: '+deliveryMode,
'Human approval: '+String(humanApproval),
'Autonomous opt-in: '+String(autonomous),
'Dispatch allowed: '+String(dispatchAllowed)
].join('\n'),lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,external_id:approvalId,external_source:'wholesaling-os-offer-approval',metadata:{approval_id:approvalId,request_id:requestId||null,offer_amount:offer,mao_ceiling:mao,delivery_mode:deliveryMode,dispatch_allowed:dispatchAllowed,guardrails}};
return[{json:{ok:status==='dispatch_ready'||status==='ready_for_review',status,approval_id:approvalId,request_id:requestId||null,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},offer:{amount:offer,mao_ceiling:mao,within_mao:Number.isFinite(offer)&&Number.isFinite(mao)&&offer<=mao},approval:{required:approvalRequired,human_approval:humanApproval,autonomous_opt_in:autonomous,dispatch_allowed:dispatchAllowed,delivery_mode:deliveryMode},guardrails,crm_activity:activity,missing_requirements:[...new Set(missing)],next_workflow:status==='dispatch_ready'?'wf-036-offer-lifecycle':status==='approval_required'?'human_approval':'offer_review'}}];
